symbols.signature:
type CataloguedProp = {
    readonly name: string;
    readonly required: boolean;
};

type CataloguedPrimitive = {
    readonly type: PrimitiveType;
    /** One line, written by the primitive's author, about what it is for. */
    readonly description: string;
    /**
     * Declared props, name-sorted. `undefined` when the declared schema is not an
     * object schema and its keys therefore cannot be enumerated — unknown, which
     * is not the same claim as "none".
     */
    readonly props: readonly CataloguedProp[] | undefined;
    readonly slots: readonly SlotName[];
    /**
     * The binding names this primitive reads an answer under, in declaration
     * order. `undefined` when its author has not said — which, like `props`, is
     * not the same claim as "none" and is not rounded to one.
     *
     * An entry is a name, or the prop that gives one and the name it falls back
     * to. The second form is carried out rather than flattened to its
     * default, because the two say different things to a model: one name it must
     * write, against one name it may replace by setting a prop.
     *
     * It is the one field here that is about what the primitive *asks the
     * deployment for* rather than about what a tree may write on it, and it is
     * here because the name in a binding belongs to the primitive. A model is
     * told which sources exist by the data catalogue; without this it was never
     * told which names those answers may be filed under, so the only name it
     * could write was one it had seen on the page already.
     */
    readonly reads: readonly BindingDeclaration<BindingName>[] | undefined;
};

type ClosedChoice = {
    readonly name: string;
    readonly options: readonly (string | boolean)[];
};

type SourceRequest<TParams> = {
    readonly params: TParams;
    /** The render request's opaque host context — audience, locale, tenant. */
    readonly context: JsonObject | undefined;
    /**
     * Aborted once the render has stopped waiting for this binding, which it will
     *. An adapter that ignores it still cannot delay the page; what it holds
     * on to is a connection whose answer nothing will read. Pass it to whatever
     * does the IO — `fetch`, a driver's query options — and the pool gets it back.
     */
    readonly signal: AbortSignal | undefined;
};

type SourceFailure = {
    /**
     * `unavailable` is "ask again later" — a timeout, a dead connection.
     * `refused` is "not for you" — an integration nobody connected, a record this
     * audience may not see. They are separate because a primitive shows different
     * things for them, and because only one of the two is worth retrying.
     */
    readonly code: "unavailable" | "refused";
    readonly detail: string;
};

interface DataAdapter<TParams = JsonObject, TAnswer extends JsonValue = JsonValue> {
    readonly fetch: (request: SourceRequest<TParams>) => Promise<Result<TAnswer, SourceFailure>>;
}

type DataUnavailable = {
    readonly reason: "no-such-source" | "not-resolved" | "invalid-params" | "invalid-answer" | "adapter-threw" | SourceFailure["code"];
    readonly detail: string;
};

type SourceDefinition<TParams, TAnswer extends JsonValue> = {
    readonly id: string;
    /** One line, for the catalogue. A model choosing a source has this to go on. */
    readonly description: string;
    /**
     * What the tree may ask with. Required, with no "anything" option: params are
     * AI-authored, and a source that declines to say what it accepts is asking the
     * deployment to trust a model's guess about its own query.
     */
    readonly params: ZodType<TParams, ZodTypeDef, unknown>;
    /**
     * What it promises to answer with. Checked at the seam even though the adapter
     * is typed by it, because the adapter's type is a claim about a database and
     * the schema is the only thing that makes it true on the day the column
     * changed.
     */
    readonly answers: ZodType<TAnswer, ZodTypeDef, unknown>;
    readonly adapter: DataAdapter<TParams, TAnswer>;
};

type SourceEntry = {
    readonly id: string;
    readonly description: string;
    readonly declaredParams: readonly CataloguedProp[] | undefined;
    /** Total: validates, calls, catches, validates again. Never rejects. */
    readonly answer: (params: JsonObject, context: JsonObject | undefined, signal?: AbortSignal) => Promise<Result<JsonValue, DataUnavailable>>;
};

type RegisteredSource = SourceEntry & {
    readonly id: SourceId;
};

type DataRegistryError = {
    readonly code: "invalid-source-id";
    readonly id: string;
} | {
    readonly code: "duplicate-source-id";
    readonly id: string;
};

interface DataRegistry {
    readonly source: (id: SourceId) => RegisteredSource | undefined;
    /** In registration order, so a catalogue reads predictably. */
    readonly sources: readonly RegisteredSource[];
}

type Binding = {
    readonly source: SourceId;
    readonly params: JsonObject;
};

type BindingError = {
    /** The path of the offending entry, for a diagnostic a person can act on. */
    readonly path: string;
    readonly message: string;
};

type CataloguedSource = {
    readonly id: SourceId;
    /** One line, written by the source's author, about what it answers. */
    readonly description: string;
    /**
     * Declared params, name-sorted. `undefined` when the declared schema is not an
     * object schema and its keys therefore cannot be enumerated — unknown, which
     * is not the same claim as "none".
     */
    readonly params: readonly CataloguedProp[] | undefined;
};

type PlannedRequest = {
    readonly key: RequestKey;
    readonly source: SourceId;
    readonly params: JsonObject;
};

type PlannedBinding = {
    readonly nodeId: NodeId;
    readonly name: BindingName;
    readonly key: RequestKey;
};

type BindingProblem = {
    readonly nodeId: NodeId;
    readonly error: BindingError;
};

type DataPlan = {
    /** Deduplicated, in first-encountered order. */
    readonly requests: readonly PlannedRequest[];
    readonly bindings: readonly PlannedBinding[];
    readonly problems: readonly BindingProblem[];
};

type DataOutcome = {
    readonly status: "ready";
    readonly value: JsonValue;
} | {
    readonly status: "unavailable";
    readonly unavailable: DataUnavailable;
};

type NodeDataProblem = {
    readonly kind: "misdeclared";
    readonly error: BindingError;
} | {
    readonly kind: "unavailable";
    readonly name: BindingName;
    readonly source: SourceId;
    readonly unavailable: DataUnavailable;
};

interface DataResolution {
    /**
     * Always answers. `NO_DATA` means *this node asked for nothing* — it is not a
     * way to say "I have no answers for you", and an implementation that uses it as
     * one is reporting an absence as a satisfied request.
     *
     * The render walk holds a resolution to that: a node that declares bindings and
     * gets `NO_DATA` with no problems beside it earns a `data-unresolved`
     * diagnostic, because the only way to be in that state honestly is to have been
     * built from a different tree's plan.
     */
    readonly lookup: (nodeId: NodeId) => NodeData;
    readonly problemsFor: (nodeId: NodeId) => readonly NodeDataProblem[];
}

type ResolveDataOptions = {
    readonly registry: DataRegistry;
    /** Passed through to every adapter — the render request's host context. */
    readonly context?: JsonObject;
    /**
     * How long any one source is given, each independently of the others. Defaults
     * to `DEFAULT_SOURCE_CEILING_MS`; there is no way to wait forever.
     */
    readonly ceilingMs?: number;
};

type CataloguedFrameOrigin = {
    readonly origin: FrameOrigin;
    /** One line, written by whoever runs the deployment. */
    readonly description: string;
};

type FrameOriginDefinition = {
    readonly origin: string;
    /** One line, for the catalogue — "Vimeo player embeds". */
    readonly description: string;
    /**
     * Whether this origin is the deployment's own.
     *
     * It changes nothing about whether a frame is permitted and everything about
     * what the frame is worth. A primitive's `sandbox` is only a sandbox at all
     * *because* the framed document is cross-origin: `allow-scripts` beside
     * `allow-same-origin` on a document from this very origin re-grants the
     * document full access to the page that framed it. Nothing in a render could
     * previously tell — this is the one place that can, because it is the only
     * place that knows what "own" means for this deployment.
     */
    readonly self?: boolean;
};

type RegisteredFrameOrigin = {
    readonly origin: FrameOrigin;
    readonly description: string;
    readonly self: boolean;
};

type FrameOriginRegistryError = {
    readonly code: "invalid-frame-origin";
    readonly origin: string;
    readonly detail: string;
} | {
    readonly code: "duplicate-frame-origin";
    readonly origin: string;
};

interface FrameOriginRegistry {
    /** `undefined` when nothing registered covers the URL's origin. */
    readonly origin: (url: URL) => RegisteredFrameOrigin | undefined;
    /** In registration order, so a catalogue reads predictably. */
    readonly origins: readonly RegisteredFrameOrigin[];
}

type FrameOutcome = {
    readonly status: "allowed";
    /**
     * The URL to place, normalised through `URL`. Normalised rather than
     * echoed so that what the browser resolves is what this seam checked —
     * a `src` that differed from the string the allowlist was matched against
     * would make the check advisory.
     */
    readonly url: string;
    readonly origin: FrameOrigin;
    /**
     * The framed document is this deployment's own, so the primitive's
     * `sandbox` grants it nothing: `allow-scripts` with `allow-same-origin`
     * is only a boundary between two origins. Permitted — a host that
     * registered its own origin meant to — and said out loud, in the render's
     * diagnostics and here, because it is the one thing about a frame that
     * looks safe and is not.
     */
    readonly sameOrigin: boolean;
} | {
    readonly status: "refused";
    readonly refusal: FrameRefusal;
};

type FrameRefusal = {
    readonly reason: /** No allowlist was wired, so this deployment frames nothing. */ "no-registry" | /** Parsed, and nobody registered its origin. */ "unlisted-origin" | /** Not an absolute http(s) URL at all — so it has no origin to check. */ "unframeable";
    readonly detail: string;
};

interface IdFactory {
    readonly nodeId: () => NodeId;
    readonly treeId: () => TreeId;
    readonly deltaId: () => DeltaId;
    readonly intentId: () => IntentId;
    readonly proposalId: () => ProposalId;
}

type InteractiveWhen = "always" | {
    readonly whenProps: readonly string[];
};

type ModelRequest = {
    readonly model: string;
    readonly maxTokens: number;
    readonly effort: ModelEffort;
    readonly system: string;
    readonly userMessage: string;
    /** JSON Schema the reply is constrained to. */
    readonly outputSchema: JsonObject;
};

type ModelCompletion = {
    /** The reply body, expected to be JSON matching `outputSchema`. */
    readonly text: string;
    /** The model that actually served the request, which may differ from the one asked for. */
    readonly servedBy: string;
};

type ModelClientError = {
    readonly code: "unavailable";
    readonly detail: string;
} | {
    readonly code: "rejected";
    readonly detail: string;
} | {
    readonly code: "misconfigured";
    readonly detail: string;
} | {
    readonly code: "refused";
    readonly detail: string;
} | {
    readonly code: "incomplete";
    readonly detail: string;
};

interface ModelClient {
    readonly complete: (request: ModelRequest, options?: ModelCallOptions) => Promise<Result<ModelCompletion, ModelClientError>>;
}

type DraftNode = {
    readonly kind: "element";
    readonly type: PrimitiveType;
    readonly props: string;
    readonly children: readonly DraftNode[];
} | {
    readonly kind: "text";
    readonly value: string;
};

type ModelInterpreterConfig = PromptVocabularies & {
    readonly client: ModelClient;
    readonly idFactory: IdFactory;
    readonly clock: Clock;
    readonly model?: string;
    readonly maxTokens?: number;
    readonly effort?: ModelEffort;
    /**
     * How long to wait for a reply before reporting that there was not one.
     * Defaults to `DEFAULT_INTERPRETER_CEILING_MS`; there is no way to wait
     * forever, deliberately.
     */
    readonly ceilingMs?: number;
    readonly draftDepth?: number;
};

type MaterializeContext = {
    readonly treeId: TreeId;
    readonly baseRevision: number;
    readonly deltaId: DeltaId;
    readonly idFactory: IdFactory;
};

type PromptVocabularies = {
    /**
     * What this deployment can build with. Absent means the model is told only
     * what the tree shows, which is what §2 shipped with; a host that has a §4
     * registry projects it with `catalogueOf` and the model stops guessing at
     * primitive names it has no way to know.
     */
    readonly catalogue?: PrimitiveCatalogue;
    /**
     * What this deployment may be themed with. Absent means the model is shown no
     * theme vocabulary and cannot re-theme anything: the ids in the tree are the
     * only ones it knows, so "make it warmer" has nowhere to go but an invented
     * id that fails to resolve. A host with a §4b theme registry passes
     * `themes.catalogue()`.
     */
    readonly themeCatalogue?: ThemeCatalogue;
    /**
     * What this deployment can be asked about. Absent means the model is told
     * nothing about the data seam, so the only bindings it can propose are ones
     * it invented — refused at the seam as `no-such-source`, which is the right
     * refusal for a guess nobody gave it the information to avoid. A host
     * with a source registry passes `dataCatalogue(registry)`.
     */
    readonly dataCatalogue?: DataCatalogue;
    /**
     * Where this deployment will accept a submission. Absent means the model
     * cannot point a form anywhere, which is the safe default rather than a gap:
     * `loom:submit` names a registered endpoint and nothing else leaves the tree
     *. A host with an endpoint registry passes
     * `submissionCatalogue(registry)`.
     */
    readonly submissionCatalogue?: SubmissionCatalogue;
    /**
     * Whose documents this deployment will frame. Absent means the model is not
     * told, and a frame it proposes renders a refusal unless it happened to name
     * a registered origin. Unlike the four above this one narrows a value the
     * model still chooses, because which video belongs on a page is a content
     * decision and the URL stays in the tree.
     */
    readonly frameCatalogue?: FrameCatalogue;
};

type PromptMeasurement = {
    readonly system: number;
    readonly primitives: number;
    readonly themes: number;
    readonly sources: number;
    readonly endpoints: number;
    readonly frames: number;
    readonly tree: number;
    readonly request: number;
    /** The sum of the eight, and what actually goes over the wire. */
    readonly total: number;
};

type CataloguedCost = {
    readonly type: PrimitiveType;
    readonly characters: number;
};

type CatalogueCost = {
    readonly entries: number;
    /** The block as sent, the instruction around the list included. */
    readonly characters: number;
    /** The mean cost of one entry, rounded. `0` for a catalogue with no entries. */
    readonly perEntry: number;
    /** What each entry costs, in catalogue order. */
    readonly byType: readonly CataloguedCost[];
};

type RepairMeasurement = {
    readonly proposal: PromptMeasurement;
    /** The refused delta, rendered, and the reasoning offered for it. */
    readonly refused: number;
    /** The Gate's reason code and its detail. */
    readonly objection: number;
    /** The closing sentence that makes this a revision rather than a fresh ask. */
    readonly instruction: number;
    /** `proposal.total` plus the three above: what the repair puts on the wire. */
    readonly total: number;
    /** `proposal.total + total`: the whole refused-then-repaired episode. */
    readonly episode: number;
};

type JsonValue = string | number | boolean | null | JsonValue[] | {
    [key: string]: JsonValue;
};

type LimitBounds = {
    /** Used when the caller named no limit, or named one that is not a number. */
    readonly fallback: number;
    readonly max: number;
};

type PageEnds = {
    readonly older: string | null;
    readonly newer: string | null;
};

const pageEnds: (positions: readonly number[], direction: PageDirection, { beyond, resumed }: {
    readonly beyond: boolean;
    readonly resumed: boolean;
}) => PageEnds

type PartitionedProps = {
    /** What the primitive and the validator see. */
    readonly props: JsonObject;
    /** What the runtime reads, keyed as it appears in the tree. */
    readonly reserved: JsonObject;
};

type Result<TValue, TError> = {
    readonly ok: true;
    readonly value: TValue;
} | {
    readonly ok: false;
    readonly error: TError;
};

type ChangeAssessment = {
    readonly proposal: ProposedChange;
    readonly analysis: ChangeAnalysis;
    readonly stakes: StakeAssessment;
    readonly reversibility: Reversibility;
};

type DispositionReason = {
    readonly code: DispositionReasonCode;
    readonly detail: string;
};

type Disposition = {
    readonly kind: DispositionKind;
    readonly reason: DispositionReason;
    readonly stakes: StakeLevel;
    readonly reversible: boolean;
    readonly confidence: number;
    readonly policyId: string;
    /** Absent on a judgment recorded before the Gate fingerprinted policies. */
    readonly policyFingerprint?: string;
};

type RuntimeEvent = {
    readonly type: "intent-received";
    readonly intent: EditIntent;
}
/**
 * Which policy this intent will be judged under, settled before anything is
 * interpreted. Emitted even for an intent that never reaches a disposition,
 * because "which policy was in force" is a question about the ask rather than
 * about the answer — and an interpretation failure under a strict policy and
 * one under a lax policy are not the same event.
 *
 * It carries the whole policy: within a request the next stage needs the
 * values, not the name. What survives is narrower.
 */
 | {
    readonly type: "policy-resolved";
    readonly intentId: IntentId;
    readonly policy: GatePolicy;
} | {
    readonly type: "interpretation-failed";
    readonly intent: EditIntent;
    readonly error: InterpretationError;
} | {
    readonly type: "change-proposed";
    readonly proposal: ProposedChange;
} | {
    readonly type: "assessment-failed";
    readonly proposal: ProposedChange;
    readonly error: TreeError;
} | {
    readonly type: "change-assessed";
    readonly assessment: ChangeAssessment;
} | {
    readonly type: "disposition-decided";
    readonly proposalId: ProposalId;
    readonly disposition: Disposition;
}
/**
 * A refusal was handed back for one more attempt. Emitted *after* the
 * refusal's own `disposition-decided`, never instead of it: a change that was
 * refused and then repaired into something acceptable must leave both halves
 * of that story in the record, or the pattern becomes invisible.
 */
 | {
    readonly type: "repair-requested";
    readonly refusedProposalId: ProposalId;
    readonly reason: DispositionReason;
} | {
    readonly type: "repair-failed";
    readonly refusedProposalId: ProposalId;
    readonly error: InterpretationError;
} | {
    readonly type: "change-applied";
    readonly proposalId: ProposalId;
    readonly revision: number;
    readonly inverse: TreeDelta;
} | {
    readonly type: "application-failed";
    readonly proposalId: ProposalId;
    readonly error: TreeError;
}
/**
 * An intent that never reached interpretation, because the tree it named had
 * already moved on. Narrated rather than silently returned: a rising rate of
 * this is contention, and it is the one failure a client is expected to
 * recover from on its own.
 */
 | {
    readonly type: "intent-not-writable";
    readonly intent: EditIntent;
    readonly error: StoreError;
}
/**
 * The Gate held a change back and custody of it succeeded, so there is
 * something for a human to answer. Distinct from the `disposition-decided`
 * that preceded it: one is a judgment, the other is a proposal that still
 * exists to be confirmed.
 */
 | {
    readonly type: "proposal-held";
    readonly proposalId: ProposalId;
}
/**
 * Custody failed, so a change the Gate was willing to offer is simply gone.
 * Emitted because the alternative is a change that disappears between two
 * events that both say things went well.
 */
 | {
    readonly type: "hold-failed";
    readonly proposalId: ProposalId;
    readonly detail: string;
}
/**
 * A human answered a held proposal. The disposition that follows is the Gate's
 * second look.
 *
 * `actor` is who answered, which is not who asked: a hold exists precisely
 * because the Gate wanted a second person, and provenance records only the
 * first. This event is the only place the approval is attributed, so a
 * host that drops it keeps the change and loses who allowed it.
 */
 | {
    readonly type: "hold-confirmed";
    readonly proposalId: ProposalId;
    readonly actor?: string;
}
/**
 * A human answered no. The most valuable event in this list for §6: it is the
 * only one that says a change the Gate was prepared to allow was not wanted,
 * which is what calibration has to learn from — and a refusal is only
 * evidence about a reviewer if it says which one.
 */
 | {
    readonly type: "hold-discarded";
    readonly proposalId: ProposalId;
    readonly actor?: string;
}
/**
 * The delta reached the log. `change-applied` says a tree in memory accepted
 * it; this says the truth moved.
 */
 | {
    readonly type: "change-committed";
    readonly proposalId: ProposalId;
    readonly revision: number;
}
/**
 * Accepted, applied in memory, and then not persisted. The gap between
 * `change-applied` and this is the one place the event stream could lie about
 * what a tree contains, so it is narrated rather than returned only to the
 * caller.
 */
 | {
    readonly type: "commit-failed";
    readonly proposalId: ProposalId;
    readonly error: StoreError;
};

type RuntimeEventEnvelope = {
    readonly treeId: TreeId;
    readonly occurredAt: string;
    readonly event: RuntimeEvent;
};

interface EventSink {
    readonly emit: (envelope: RuntimeEventEnvelope) => void;
}

type EditIntent = {
    readonly intentId: IntentId;
    readonly treeId: TreeId;
    readonly baseRevision: number;
    readonly origin: IntentOrigin;
    readonly actor?: string;
    readonly utterance: string;
    readonly scopeNodeId?: NodeId;
    readonly observedAt: string;
};

type InterpretationError = {
    readonly code: "not-understood";
    readonly detail: string;
} | {
    readonly code: "no-change-needed";
    readonly detail: string;
}
/** The service could not answer now. The same request may succeed later. */
 | {
    readonly code: "interpreter-unavailable";
    readonly detail: string;
}
/**
 * This deployment cannot reach a model at all — no credential, no entitlement,
 * no billing. Kept apart from `interpreter-unavailable` because waiting never
 * fixes it: an operator does.
 */
 | {
    readonly code: "interpreter-misconfigured";
    readonly detail: string;
}
/**
 * The service rejected the request Loom assembled, and would reject the same
 * request again. This one is Loom's own fault, and it is the only failure here
 * that a deployment can neither wait out nor configure away.
 */
 | {
    readonly code: "interpreter-request-rejected";
    readonly detail: string;
}
/**
 * The interpreter itself declined — a safety classifier, a content policy, a
 * guardrail of its own. Kept apart from `interpreter-unavailable` because one
 * is a statement about the request and the other is a statement about the
 * service: a rising rate of the first is a content signal, a rising rate of
 * the second is an outage.
 */
 | {
    readonly code: "refused";
    readonly detail: string;
} | {
    readonly code: "malformed-proposal";
    readonly detail: string;
};

type InterpretationFault = 
/** The intent: nothing failed except the asking. */
"asker"
/** The answer that came back. */
 | "model"
/** The service, this time. */
 | "provider"
/** The deployment, until someone changes it. */
 | "deployment"
/** Loom, for what it sent. */
 | "runtime";

interface ChangeInterpreter {
    readonly interpret: (intent: EditIntent, tree: LoomTree) => Promise<Result<ProposedChange, InterpretationError>>;
}

type RepairRequest = {
    readonly intent: EditIntent;
    readonly refused: ProposedChange;
    readonly disposition: Disposition;
};

interface ChangeRepairer {
    readonly repair: (request: RepairRequest, tree: LoomTree) => Promise<Result<ProposedChange, InterpretationError>>;
}

type ComputedInverse = {
    /** The undo, as operations. The delta's id and base belong to the proposal. */
    readonly operations: readonly TreeOperation[];
    /**
     * The revision the operations were computed against.
     *
     * An inverse is only an inverse of one arrangement. Offered against another it
     * would be proposing something whose reasoning has expired, so the interpreter
     * declines rather than proposing it — which is what makes this safe to wire
     * into a runtime directly, with no write path in front of it.
     */
    readonly headRevision: number;
    /** What produced the delta, for `Provenance.interpreter`. Not a model. */
    readonly interpreter: string;
    /** Why, in the words the person answering a hold reads. */
    readonly rationale: string;
    /**
     * Work this undo writes over, when the caller knows of some.
     *
     * Only a caller that read a log can know, so it is absent by default and
     * absence keeps meaning "nobody looked" rather than "a log was checked and was
     * clean".
     */
    readonly discards?: readonly DiscardedWork[];
    /**
     * The revision this puts back, recorded on the provenance the log keeps.
     *
     * Optional because not every inverse has one to name. A stateless surface
     * undoing a change it made in the same session has no revision — nothing was
     * ever appended — and stamping a number it does not have would be worse than
     * the absence. A caller that planned the undo off a log always does.
     */
    readonly undoes?: number;
};

type NestedTarget = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /** The nearest target above it, which is the one that swallows it. */
    readonly ancestorId: NodeId;
    readonly ancestorType: PrimitiveType;
};

type CompositionRuntime = {
    readonly interpreter: ChangeInterpreter;
    /**
     * Which policy judges a given change. A source rather than a policy, because
     * one runtime may serve trees that do not deserve the same latitude; a host
     * with one policy says so with `fixedPolicy`.
     */
    readonly policySource: PolicySource;
    readonly events: EventSink;
    readonly clock: Clock;
    readonly idFactory: IdFactory;
    /**
     * Optional, and absent by default. With no repairer, a refusal is terminal.
     * With one, a refused proposal gets exactly one more attempt — see
     * `attemptRepair`, where the "exactly one" is structural rather than a
     * counter that could drift.
     */
    readonly repairer?: ChangeRepairer;
    /**
     * What this deployment's primitives accept, checked before a delta is judged.
     * Optional, and absent by default: a runtime handed none cannot check props,
     * so "this deployment refuses AI-authored props its own schemas reject" is a
     * visible choice at the composition root rather than a property of whichever
     * interpreter happened to be wired in.
     *
     * Deliberately the same shape as the renderer's `PropsValidator`, so a host
     * with a registry hands the same object to both seams and the two cannot
     * disagree about what is drawable. `propsVocabularyFor(registry)` in the SDK
     * is how one is obtained without hand-keeping it.
     */
    readonly propsVocabulary?: PropsVocabulary;
};

type CompositionOutcome = {
    readonly kind: "applied";
    readonly tree: LoomTree;
    readonly assessment: ChangeAssessment;
    readonly disposition: Disposition;
    readonly inverse: TreeDelta;
} | {
    readonly kind: "awaiting-confirmation";
    readonly assessment: ChangeAssessment;
    readonly disposition: Disposition;
} | {
    readonly kind: "rejected";
    readonly assessment: ChangeAssessment;
    readonly disposition: Disposition;
    /**
