     * fallback. A reference with a fallback is not reported: the fallback is the
     * value, exactly as it is in a browser, and `--loom-mono-family` is written
     * that way on purpose.
     */
    readonly unresolved: readonly string[];
};

type InlinedProjection = {
    readonly element: ReactNode;
    readonly unresolved: readonly string[];
};

type LoomPrimitiveProps<TProps extends JsonObjectView = JsonObject, TText extends string = never, TBehaviour extends BehaviourName = never> = {
    readonly loom: LoomRenderContext<TText, TBehaviour>;
    /** The node's props, exactly as they appear in the tree. */
    readonly props: TProps;
    /** Rendered children in tree order, or null when the node has none. */
    readonly children: ReactNode;
};

interface PrimitiveResolver {
    readonly resolve: (type: PrimitiveType) => LoomPrimitive | undefined;
}

type PropsIssue = {
    /** Dotted path within the props object; `props` when the whole bag is wrong. */
    readonly path: string;
    /**
     * Developer-facing text from the declaring schema. Zod's own messages can
     * name a rejected value (an enum mismatch quotes what it received), so a
     * consumer must treat this as content rather than as a safe-to-log constant.
     */
    readonly message: string;
};

type PropsVerdict = {
    readonly outcome: "valid";
} | {
    readonly outcome: "invalid";
    readonly issues: readonly PropsIssue[];
}
/** The validator has no schema for this type — see `render.ts` for what that means. */
 | {
    readonly outcome: "undeclared";
};

interface PropsValidator {
    readonly validateProps: (type: PrimitiveType, props: JsonObject) => PropsVerdict;
}

type BindingDeclaration<Name extends string = string> = Name | {
    /** The prop whose value is the name. Declared by the primitive's schema. */
    readonly fromProp: string;
    /** The name read when that prop is absent, which is the common case. */
    readonly default: Name;
};

interface BindingReader {
    readonly bindingsReadBy: (type: PrimitiveType) => readonly BindingDeclaration[] | undefined;
}

type RenderOptions = {
    readonly resolver: PrimitiveResolver;
    /**
     * Absent means props are not checked against declared schemas. A registry
     * built by §4's SDK satisfies both this and `resolver`, so wiring the same
     * object into both is the ordinary case.
     */
    readonly validator?: PropsValidator;
    /**
     * Absent means the tree's theme is not resolved and nothing is mounted, and
     * a tree that names one says so in a diagnostic. Supplying a registry is what
     * bounds the palettes, font packs and style presets a proposal may name.
     */
    readonly themes?: ThemeRegistry;
    /**
     * Absent means the tree's bindings are not answered, and a tree that declares
     * one says so in a diagnostic. Resolution is async and rendering is not, so it
     * happens before the walk — `renderRequest` does it, and a caller driving
     * `renderLoomTree` itself resolves with `resolveTreeData` first.
     */
    readonly data?: DataResolution;
    /**
     * Absent means the tree's submissions are not answered, and a tree that names
     * an endpoint says so in a diagnostic. Resolution may do IO — minting a token
     * usually does — so it happens before the walk, the same way data does;
     * `renderRequest` does it, and a caller driving `renderLoomTree` itself
     * resolves with `resolveTreeSubmissions` first.
     */
    readonly submissions?: SubmissionResolution;
    /**
     * The origins this deployment is willing to frame. Absent means every
     * framable prop is refused, and each one says so in a diagnostic — the seam
     * fails closed, because the registry *is* the allowlist and a deployment that
     * has not written one has not agreed to run anybody's script inside its
     * pages.
     *
     * Unlike `data` and `submissions` there is nothing to resolve first: an
     * allowlist is static, so the check happens in the walk.
     */
    readonly origins?: FrameOriginRegistry;
    /**
     * The host's answer for the strings primitives declared — a dictionary, in the
     * language this deployment serves. Absent means the declared strings render as
     * their authors wrote them, which is what an untranslated deployment wants and
     * needs no wiring: the renderer reads declarations off `resolver` when that
     * resolver is a registry. `textResolverFor` builds one of these from a
     * registry and a dictionary.
     *
     * A key this does not answer keeps its declared string, so a partial
     * dictionary is a partial translation rather than a missing accessible name.
     * There is deliberately no wiring that suppresses a declared string: a control
     * with no accessible name is the failure the seam exists to prevent, and it
     * should not be reachable by leaving something out.
     */
    readonly text?: TextResolver;
    /** Off by default: decoration is opt-in per request, never ambient. */
    readonly editMode?: boolean;
    /**
     * Stamp each element's identity on the markup without anything else edit mode
     * means, so a published page can say which node a reader saw or clicked.
     *
     * Off by default, and the markup is byte-identical when it is off. It writes
     * exactly the attributes edit mode writes — node id and type on every
     * decorated element, the tree id and revision on the root — because those are
     * the addresses an event about a reader has to carry.
     */
    readonly addressed?: boolean;
    readonly slots?: SlotContent;
    readonly themeValues?: "variables" | "literals";
};

type RenderOutput = {
    readonly element: ReactNode;
    readonly diagnostics: readonly RenderDiagnostic[];
    /**
     * What the root is wearing, absent when the tree named no theme or the render
     * could not resolve it. The variables are already mounted; this is here so a
     * caller can *say* which palette it served without resolving the ids again.
     */
    readonly theme?: ResolvedTheme;
};

type ExcerptOutput = RenderOutput & {
    /**
     * Whether the tree holds the node asked for. `false` comes with a null
     * element and an `excerpt-absent` diagnostic; it is here because it is the
     * one thing every caller branches on, and scanning a diagnostic array to
     * decide whether to render a fallback is worse than being told.
     */
    readonly found: boolean;
};

type RenderRequest = {
    readonly treeId: TreeId;
    /** Decoration is a property of the request, so one process can serve both. */
    readonly editMode: boolean;
    /**
     * Identity on a published page's markup, so reader signals can name the node
     * they are about. Off when absent.
     */
    readonly addressed?: boolean;
    /** Opaque host context — audience, locale, flags — passed through to the source. */
    readonly context?: JsonObject;
};

type TreeSourceError = {
    readonly code: "not-found" | "unavailable";
    readonly detail: string;
};

interface TreeSource {
    readonly load: (request: RenderRequest) => Promise<Result<unknown, TreeSourceError>>;
}

type RenderDependencies = {
    readonly source: TreeSource;
    readonly resolver: PrimitiveResolver;
    readonly validator?: PropsValidator;
    /** Absent means the tree's theme is not resolved — see `RenderOptions.themes`. */
    readonly themes?: ThemeRegistry;
    /**
     * Absent means the tree's bindings are not answered — see `RenderOptions.data`.
     * Supplying a registry is what bounds the sources a proposal may name, the
     * same way `themes` bounds the palettes.
     */
    readonly sources?: DataRegistry;
    /**
     * Absent means the tree's submissions are not answered — see
     * `RenderOptions.submissions`. Supplying a registry is what bounds the
     * destinations a proposal may name, and it is the only thing that does: an
     * address never appears in a tree, so a deployment that registers nothing has
     * no form that posts anywhere.
     */
    readonly endpoints?: EndpointRegistry;
    /**
     * The origins this deployment will frame — see `RenderOptions.origins`.
     * Absent means every framable prop is refused with a diagnostic.
     *
     * It sits here beside the other three registries and, unlike them, adds no
     * `await`: an allowlist is a static fact, so it is passed straight through to
     * the walk rather than resolved first.
     */
    readonly origins?: FrameOriginRegistry;
    /**
     * Absent means primitives render the strings their authors declared — see
     * `RenderOptions.text`. A host serving one language in the library's own
     * language wires nothing here; a host serving another builds a resolver per
     * dictionary and picks by whatever it reads the request's language from, which
     * is its own business and not the framework's.
     */
    readonly text?: TextResolver;
    readonly slots?: SlotContent;
    /**
     * References or values — see `RenderOptions.themeValues`. It belongs to the
     * request rather than to the deployment: one route serves a page to a browser
     * and the next draws the same tree into an image, off the same dependencies.
     */
    readonly themeValues?: "variables" | "literals";
};

type RenderRequestError = {
    readonly code: "source-failed";
    readonly error: TreeSourceError;
} | {
    readonly code: "invalid-tree";
    readonly error: TreeError;
} | {
    readonly code: "tree-id-mismatch";
    readonly requested: TreeId;
    readonly received: TreeId;
};

type RenderedRequest = RenderOutput & {
    readonly tree: LoomTree;
};

interface TextResolver {
    readonly textFor: (type: PrimitiveType) => PrimitiveText<string>;
}

type ThemeResolution = {
    readonly outcome: "themed";
    readonly theme: ResolvedTheme;
}
/** The node names no theme — the ordinary case for every node but the root. */
 | {
    readonly outcome: "unthemed";
}
/** Named, and the registry refused it: an unknown id, or a malformed selection. */
 | {
    readonly outcome: "unresolved";
    readonly error: ThemeError;
}
/** Named, and this render was given no registry to resolve it against. */
 | {
    readonly outcome: "unregistered";
};

type PartitionedProps = {
    /** What the primitive and the validator see. */
    readonly props: JsonObject;
    /** What the runtime reads, keyed as it appears in the tree. */
    readonly reserved: JsonObject;
};

type Composition = {
    /**
     * Lower-case words joined by hyphens, the way an anchor or a slot name is.
     *
     * **A part's canonical design has the part's own name as its id**, and every
     * other design of that part is the part name plus what makes it different —
     * `hero` and `hero-split`. That convention is not cosmetic: it is what lets
     * the page sequence be *derived* rather than maintained as a second hand-kept
     * list that could disagree with the first. There is a test on it.
     */
    readonly id: string;
    /** Which band of a page this is a design of. */
    readonly part: CompositionPart;
    /** What a person choosing it from a list reads. */
    readonly label: string;
    /**
     * What lands on the page, in one clause, said before it happens.
     *
     * About the page and never about the verdict, for the reason the demo's
     * presets give: whether the Gate applies a band or holds it is computed from
     * the tree at assessment time, so a promise about the outcome would be a
     * surface predicting a decision it does not make.
     */
    readonly promise: string;
    /** The interpreter's own words about why this subtree answers that ask. */
    readonly rationale: string;
    /** Every primitive type the subtree uses, for the catalogue and the audit. */
    readonly uses: readonly string[];
    readonly build: (ids: IdFactory) => ElementNode;
};

type CompositionTarget = {
    readonly parentId?: NodeId;
    /** Clamped to the parent's current child count, never trusted as an index. */
    readonly index?: number;
};

type CompositionPlan = {
    readonly outcome: "planned";
    readonly operations: readonly TreeOperation[];
}
/**
 * The named parent is not in this tree, so there is nowhere to put the band.
 *
 * A distinct outcome rather than a silent append at the root: a band that
 * quietly landed somewhere other than where it was asked for is worse than
 * one that did not land, because the second is visible.
 */
 | {
    readonly outcome: "no-such-parent";
    readonly parentId: NodeId;
};

