const WIDTHS: {
    readonly full: "100%";
    readonly wide: "1120px";
    readonly readable: "68ch";
}

type CataloguedProp = {
    readonly name: string;
    readonly required: boolean;
};

type CataloguedPrimitive = {
    readonly type: PrimitiveType;
    /** One line, written by the primitive's author, about what it is for. */
    readonly description: string;
    /**
     * Declared props, name-sorted. `undefined` when the declared schema is not an
     * object schema and its keys therefore cannot be enumerated — unknown, which
     * is not the same claim as "none".
     */
    readonly props: readonly CataloguedProp[] | undefined;
    readonly slots: readonly SlotName[];
    /**
     * The binding names this primitive reads an answer under, in declaration
     * order. `undefined` when its author has not said — which, like `props`, is
     * not the same claim as "none" and is not rounded to one.
     *
     * An entry is a name, or the prop that gives one and the name it falls back
     * to. The second form is carried out rather than flattened to its
     * default, because the two say different things to a model: one name it must
     * write, against one name it may replace by setting a prop.
     *
     * It is the one field here that is about what the primitive *asks the
     * deployment for* rather than about what a tree may write on it, and it is
     * here because the name in a binding belongs to the primitive. A model is
     * told which sources exist by the data catalogue; without this it was never
     * told which names those answers may be filed under, so the only name it
     * could write was one it had seen on the page already.
     */
    readonly reads: readonly BindingDeclaration<BindingName>[] | undefined;
};

type PrimitiveAudit = {
    readonly type: PrimitiveType;
    readonly verdict: ConformanceVerdict;
    readonly placement: PlacementVerdict;
    readonly submission: SubmissionVerdict;
    /** What the author declared, beside what the probe saw. */
    readonly declaresSubmits: boolean;
    /** The props this primitive declared it frames. Empty for almost all. */
    readonly framesProps: readonly string[];
};

type UnplacedSlots = {
    readonly type: PrimitiveType;
    readonly slots: readonly string[];
};

type UnplacedBehaviours = {
    readonly type: PrimitiveType;
    readonly behaviours: readonly BehaviourName[];
};

type ThrowingConfigurations = {
    readonly type: PrimitiveType;
    readonly failures: readonly ProbeFailure[];
    /**
     * Whether *nothing* the probe tried came back — the line between a fault the
     * audit is certain of and one it is only reporting.
     *
     * `false`: some configurations rendered and this one threw, so the component
     * is callable and a value its own schema accepts crashes it. Certain.
     *
     * `true`: every configuration threw, which is what a broken component and a
     * hook-using one both look like from outside a renderer — and a hook-using
     * component is a legitimate primitive. A host with none of those
     * asserts the whole list empty; one that ships them asserts the `false` half
     * and reads the rest.
     */
    readonly everyConfiguration: boolean;
};

type ProbeFailure = {
    readonly props: JsonObject;
    readonly reason: string;
};

type NotProbeable = {
    readonly outcome: "not-probeable";
    readonly cause: NotProbeableCause;
    readonly reason: string;
    /** Every configuration that threw. Empty exactly when nothing was called. */
    readonly failures: readonly ProbeFailure[];
};

type ConformanceVerdict = {
    readonly outcome: "decorates";
} | {
    readonly outcome: "not-decorated";
} | NotProbeable;

type PlacementVerdict = {
    readonly outcome: "probed";
    /** Declared slots that no probed configuration placed. */
    readonly unplacedSlots: readonly string[];
    /** Declared behaviours whose control no probed configuration placed. */
    readonly unplacedBehaviours: readonly BehaviourName[];
    /** Whether any probed configuration placed the children it was handed. */
    readonly rendersChildren: boolean;
    /** The configurations that answered — `{}` alone when the schema closes over nothing. */
    readonly probed: readonly JsonObject[];
    /**
     * Configurations built from the primitive's own schema that it threw on.
     * Never a reason to distrust the verdict — the configurations that
     * answered still answered — and always a fault: a component that throws
     * on a value its schema accepts is one a valid tree can crash a page with.
     */
    readonly threw: readonly ProbeFailure[];
} | NotProbeable;

type SubmissionVerdict = {
    readonly outcome: "places";
} | {
    readonly outcome: "not-placed";
} | NotProbeable;

type ColourPairing = {
    readonly foreground: PaletteSlot;
    readonly background: PaletteSlot;
};

type ColourVerdict = {
    readonly outcome: "probed";
    /** Ink and ground both set by this primitive. */
    readonly painted: readonly ColourPairing[];
    /** Ink set here, ground left to whatever this is placed in. */
    readonly floating: readonly PaletteSlot[];
    /** Grounds this primitive puts its declared children and slots on. */
    readonly childGrounds: readonly PaletteSlot[];
} | NotProbeable;

type CopyDeclarations = {
    readonly copyFor: (type: PrimitiveType) => readonly string[] | undefined;
};

type UnreadCopy = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /**
     * Its string-valued props, in the order the node carries them.
     *
     * String-valued, and that is a decision rather than an accident. Where
     * nothing has been declared, a value that is not a string is not a candidate
     * word at all: a `loom.divider` holding `weight: 2` would otherwise be
     * reported as a part whose words a reader might lose, and every layout
     * primitive in the library would join it. The opposite call is made on the
     * declared side, and a declaration is the whole of the difference.
     */
    readonly props: readonly string[];
};

type UnspokenCopy = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /** The declared copy props holding a non-string value, in declaration order. */
    readonly props: readonly string[];
};

type NodeCopy = {
    /**
     * In reading order: each element's own declared copy before its children's,
     * because a stat's label is above the things under it and a card's title is
     * above its body. Blank and whitespace-only values are left out — a caller
     * composing a sentence wants words, and an empty string is not one.
     */
    readonly words: readonly string[];
    /** What this reading could not see. Empty when every type under it declared. */
    readonly unread: readonly UnreadCopy[];
    /** What it was told to read and could not. Empty when every declared copy prop held a string. */
    readonly unspoken: readonly UnspokenCopy[];
};

type PrimitiveEntry = {
    readonly type: string;
    readonly description: string;
    readonly slots: readonly string[];
    readonly component: LoomPrimitive;
    readonly declaredProps: readonly CataloguedProp[] | undefined;
    /**
     * The props whose accepted values can be listed, so the conformance probe can
     * ask the primitive what it does under each one rather than under whichever
     * shape it happens to take with no props at all. Empty for the
     * primitive whose rendering does not turn on a closed choice, which is most.
     */
    readonly choices: readonly ClosedChoice[];
    /** Declared strings, keys erased alongside the props type. Empty when none. */
    readonly text: PrimitiveText<string>;
    /** Absent for the ordinary primitive, which is not a target at all. */
    readonly interactive: InteractiveWhen | undefined;
    /** `false` for the ordinary primitive, which sends nothing anywhere. */
    readonly submits: boolean;
    /** Declared framable prop names, still raw: the registry is what checks them. */
    readonly frames: readonly string[];
    /** Declared behaviour names, still raw: the registry is what checks them. */
    readonly behaviours: readonly string[];
    /**
     * The declared role, still raw: the registry is what checks it, for the same
     * reason it checks a behaviour name. `undefined` for the primitive that plays
     * no part a consumer asks about, which is most of them.
     */
    readonly role: string | undefined;
    /**
     * Declared copy prop names, still raw: the registry is what checks them.
     * `undefined` is carried through rather than defaulted to `[]`, because the
     * two mean different things here and all the way out to `copyIn`.
     */
    readonly copy: readonly string[] | undefined;
    /**
     * Declared binding names, still raw: the registry is what checks them.
     * `undefined` is carried through rather than defaulted to `[]`, because the
     * two mean different things here and all the way out to the render walk.
     */
    readonly reads: readonly BindingDeclaration[] | undefined;
    readonly validate: (props: JsonObject) => PropsVerdict;
};

type DerivedPairing = {
    readonly foreground: PaletteSlot;
    readonly background: PaletteSlot;
    readonly basis: PairingBasis;
    /** The primitives that produce it, so a failure names components rather than two slot ids. */
    readonly types: readonly PrimitiveType[];
};

type ChildGround = {
    readonly ground: PaletteSlot;
    readonly types: readonly PrimitiveType[];
};

type UnprobedProps = {
    readonly type: PrimitiveType;
    readonly props: readonly string[] | undefined;
};

type RegistryPairings = {
    readonly pairings: readonly DerivedPairing[];
    /** Inks a primitive sets without painting a ground of its own. */
    readonly floating: readonly PaletteSlot[];
    /** Every ground a primitive places children on, whether or not the ramp is held to it. */
    readonly childGrounds: readonly ChildGround[];
    /**
     * Grounds children land on that the text ramp is not held to. Not a failure:
     * `accent` is here because `loom.action` fills it and answers the ink itself.
     * It is reported because a *new* ground appearing here is the signal that
     * either a primitive is painting somewhere unconsidered or the declared list
     * has fallen behind the library — the same drift this module exists to catch,
     * one level up.
     */
    readonly groundsOutsideTheRamp: readonly ChildGround[];
    /** The probe could not answer — neither a pass nor a failure. */
    readonly notProbeable: readonly PrimitiveType[];
    /**
     * Where this derivation stops seeing, by primitive. Only primitives with at
     * least one such prop appear, so an empty list is a real claim: nothing in
     * this registry hides an element behind a prop the probe cannot set.
     *
     * Reported rather than fixed, because the alternative is a probe that invents
     * a price, a date and a URL — and a pairing derived from an invented value is
     * a fact about the invention. A list that says it is read off the components
     * should be able to say which part of them it read.
