type PrimitiveNames = {
    /** The primitive type, exactly as a tree will address it. */
    readonly type: string;
    /**
     * The module basename, which is the type verbatim: `commerce.product-card.ts`.
     *
     * Dots survive where a slug would not. Folding `.` to `-` is lossy — nothing
     * can tell whether `commerce-product-card` was `commerce.product-card` or
     * `commerce-product.card` — and the registry is regenerated from the directory
     * listing, so that round trip has to be exact.
