type VisibilityObserver = {
    readonly observe: (element: Element) => void;
    readonly disconnect: () => void;
};

type VisibilityEntry = {
    readonly target: Element;
    readonly visible: boolean;
};

type ReaderSignalTypes = readonly string[] | {
    readonly [Kind in ReaderSignalKind]?: readonly string[];
};

type ReaderSignalOptions = {
    /** Called with every batch. A throw or rejection here is contained and never reaches the page. */
    readonly send?: (batch: ReaderSignalBatch) => void | Promise<void>;
    /** Which kinds to broadcast. Every kind when absent. */
    readonly kinds?: readonly ReaderSignalKind[];
    /**
     * Which primitive types to broadcast about. Every addressed type when absent.
     *
     * A list applies to every kind. An object sets it per kind — time on screen
     * for sections, activations for links — and a kind it does not name is
     * reported for every type, exactly as if `types` were absent for that kind.
     * Whether a kind is reported at all is still `kinds`.
     */
    readonly types?: ReaderSignalTypes;
    /** How often a batch is delivered. Five seconds when absent. */
    readonly flushEveryMs?: number;
    /**
     * How the broadcaster learns what is on screen. The browser's
     * `IntersectionObserver` when absent; a test passes its own.
     */
    readonly observeVisibility?: ObserveVisibility;
    /**
     * Whether a delegated signal carries the addressed nodes it happened inside.
     * On when absent.
     *
     * `activated` and `disclosed` are filed against the control a reader aimed
     * at, which is an addressed node of its own — so without the ancestry a
     * deployment can report which button was pressed and never which region it
     * was in. Off is for a host that reports on controls only and would rather
     * not carry the walk in every batch.
     */
    readonly within?: boolean;
    /** The clock. `Date.now` when absent. */
    readonly now?: () => number;
    /**
     * Where the view key's randomness comes from. The browser's
     * `crypto.getRandomValues` when absent; a test passes its own so it can name
     * the key it expects.
     */
    readonly random?: RandomBytes;
};

type ReaderSignalBroadcast = {
    /** Deliver whatever has been gathered, now. */
    readonly flush: () => void;
    /** Deliver what is left and stop observing. Safe to call twice. */
    readonly stop: () => void;
};

type ReaderSignalBroadcastError = {
    /** The root carries no tree id or revision — the page was not rendered with `addressed: true`. */
    readonly code: "unaddressed";
    readonly detail: string;
};

type CollectionRequest = {
    readonly windowMs?: number;
    /**
     * The funnels this deployment asks about. Absent means none — a pair is a
     * question somebody wrote down, and rollup does not invent questions.
     *
     * A pair added later applies to windows collected after it, never to the ones
     * already folded, because the batches those answers came from are gone. That
     * is the price of aggregates being the durable artefact and it is worth
     * knowing before a deployment waits a day for a number it will not get.
     */
    readonly pairs?: readonly FunnelPair[];
    readonly clock?: Clock;
    readonly scanLimit?: number;
};

type CollectionPlan = {
    /** Old enough to count, in ascending `seq`. */
    readonly ripe: readonly ReceivedBatch[];
    /** The position to forget below, once the counters are durable. `null` when nothing is ripe. */
    readonly before: number | null;
    /** Seen by this scan and too young. A floor rather than a total — the scan stops at the first. */
    readonly waiting: number;
};

type CollectionSummary = {
    readonly counted: number;
    readonly tallies: number;
    readonly funnels: number;
    /** Distinct page views the window held. */
    readonly views: number;
    /**
     * Batches that carried no view key, whose occurrences counted and whose views
     * did not. A rate shown without saying which denominator it used is the
     * failure mode here, so the number travels with the run that produced it.
     */
    readonly uncorrelated: number;
};

type CollectionOutcome = {
    readonly outcome: "collected";
    readonly summary: CollectionSummary;
    /** Rows the buffer removed. Below `counted` only if something else pruned first. */
    readonly removed: number;
    /** The scan filled its limit with ripe batches, so another run has work now. */
    readonly more: boolean;
}
/** Nothing is old enough yet, which is the ordinary answer on a quiet deployment. */
 | {
    readonly outcome: "nothing-ripe";
    readonly waiting: number;
}
/**
 * The counters took the window and the buffer would not drop it.
 *
 * Its own outcome because it is the one state that gets worse if it is
 * ignored: the batches are durable in the counters and still in the buffer,
 * so the next run counts them again. An operator seeing this prunes below the
 * reported position by hand, or fixes the buffer before the next run.
 */
 | {
    readonly outcome: "counted-not-forgotten";
    readonly summary: CollectionSummary;
    readonly before: number;
    readonly error: ReaderSignalStoreError;
}
/** The window was not usable. Nothing was read, counted or deleted. */
 | {
    readonly outcome: "refused";
    readonly reason: string;
}
/** Read or write failed before anything became durable. Nothing was deleted. */
 | {
    readonly outcome: "unavailable";
    readonly error: ReaderSignalStoreError;
};

type DeliverOptions = {
    /** Where to post. {@link DEFAULT_READER_SIGNAL_PATH} when absent. */
    readonly url?: string;
    /** The browser's, when absent. A test passes its own. */
    readonly beacon?: SendBeacon | null;
    /** `fetch` with `keepalive`, when absent. */
    readonly post?: PostBatch;
};

type ReaderReadings = {
    /** Total time on screen. Summed across batches, because `dwelled` is per-batch. */
    readonly dwellMs: Readonly<Record<NodeId, number>>;
    /** Nodes that came into view at all. `viewed` fires once per node per page view. */
    readonly reached: Readonly<Record<NodeId, true>>;
    /**
     * Times the node itself was used — a link followed, a button pressed, a field
     * filled.
     *
     * It is the node the signal names, which is the nearest addressed element to
     * what a reader aimed at. In the starter library that is the control, so a
     * band's count here is zero however busy the band was; `engagements` is the
     * number that is about the band.
     */
    readonly activations: Readonly<Record<NodeId, number>>;
    readonly opens: Readonly<Record<NodeId, number>>;
    readonly closes: Readonly<Record<NodeId, number>>;
    /**
     * Times a reader used something *inside* the node — pressed, followed, filled,
     * opened or closed, at any depth.
     *
     * The regions' number. Read off the ancestry a delegated signal carries, so a
     * batch whose senders did not walk contributes nothing rather than a guess.
     * Strictly inside, so a control's own use is in `activations` and never here,
     * and a subtree total is the addition.
     *
     * Occurrences rather than readers, because a fold is one page view: *how many
     * of the people reading this used something in the band* is a question about
     * many views, and it is `ReaderTally.engaged`.
     */
    readonly engagements: Readonly<Record<NodeId, number>>;
    /**
     * What each node is, as its signals reported it. Kept because a consumer
     * holding only readings would otherwise have to go back to the tree to render
     * a row, and the signals already say.
     *
     * A region named only as somewhere a press happened inside is in here too, so
     * it gets a row rather than being a number with no name.
     */
    readonly types: Readonly<Record<NodeId, PrimitiveType>>;
    readonly batches: number;
    readonly signals: number;
};

type NodeReading = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    readonly dwellMs: number;
    readonly reached: boolean;
    readonly activations: number;
    readonly opens: number;
    readonly closes: number;
    /** Times a reader used something inside it, at any depth. */
    readonly engagements: number;
};

type IngestOutcome = {
    readonly batches: number;
    readonly signals: number;
};

type IngestError = {
    readonly code: "invalid-delivery";
    /** Which batch of the delivery, so a sender with one bad batch can be told which. */
    readonly index: number;
    readonly issues: ReaderSignalParseError["issues"];
} | {
    readonly code: "too-many";
    readonly limit: number;
    readonly given: number;
} | ReaderSignalStoreError;

type IntakePolicy = {
    /** The largest delivery the door will read, in bytes. */
    readonly maxBytes: number;
    /** Deliveries one subject may make inside a window. */
    readonly deliveries: number;
    readonly windowMs: number;
    /** How many subjects the counter distinguishes before {@link CROWDED_SUBJECT}. */
    readonly subjects: number;
};

type IntakeCount = {
    readonly deliveries: number;
    readonly windowStartedAt: number;
};

type IntakeVerdict = {
    readonly code: "admitted";
    readonly count: IntakeCount;
} | {
    readonly code: "too-large";
    readonly count: IntakeCount;
    readonly limit: number;
    readonly given: number;
} | {
    readonly code: "too-often";
    readonly limit: number;
    readonly retryAfterMs: number;
};

type IntakeGate = {
    /**
     * The policy this gate counts by.
     *
     * Carried on the gate rather than left beside it, because a caller holding
     * both had two copies that could disagree — and the one that decides is
     * whichever the gate was built with, silently. A door has one policy.
     */
    readonly policy: IntakePolicy;
    readonly admit: (subject: string, bytes: number, now: number) => IntakeVerdict;
    /** How many subjects are being counted. For a status endpoint, not for a decision. */
    readonly subjects: () => number;
};

type ReaderSignalStoreError = {
    readonly code: "unavailable";
    readonly detail: string;
};

type ReceivedBatch = ReaderSignalBatch & {
    readonly seq: number;
    readonly receivedAt: string;
};

type ReaderSignalReadRequest = {
    /** Absent reads every tree the handle can see, which is the scope rule. */
    readonly treeId?: TreeId;
    /** A cursor from a previous page's `older`/`newer`, passed back unread. */
    readonly cursor?: string;
    /** Default `newer`, which with no cursor is the oldest page — where rollup starts. */
    readonly direction?: PageDirection;
    readonly limit?: number;
};

type ReaderSignalPage = PageEnds & {
    /** Always ascending by `seq`, whichever end the page was taken from. */
    readonly batches: readonly ReceivedBatch[];
};

interface ReaderSignalJournal {
    readonly receive: (batches: readonly ReaderSignalBatch[]) => Promise<Result<void, ReaderSignalStoreError>>;
    readonly read: (request?: ReaderSignalReadRequest) => Promise<Result<ReaderSignalPage, ReaderSignalStoreError>>;
    readonly forget: (request: ForgetBefore) => Promise<Result<ForgetOutcome, ReaderSignalStoreError>>;
}

type ReaderTally = {
    readonly treeId: TreeId;
    readonly revision: number;
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /** Distinct page views that produced any signal at all about this node. */
    readonly views: number;
    /** Distinct page views in which it came into view. The denominator of a funnel. */
    readonly reached: number;
    /**
     * Distinct page views in which a reader used something *inside* this node —
     * pressed a link or button, filled a field, opened or closed a disclosure.
     *
     * The counter regions are reported by, and the only one that needs a signal to
     * say more than which node it is about. A press is filed against the control,
     * and every control in the starter library is an addressed node of its own, so
     * `activations` on a band is nearly always zero and always will be: the band
     * is not the thing anybody pressed. This counts the views whose reader did
     * something under it, at any depth, from the ancestry a delegated signal
     * carries.
     *
     * **Strictly inside.** A button's own `engaged` is 0 while its `activations`
     * is 1; its band's is the other way round. The two never double-count the same
     * node, and a subtree total is the addition.
     *
     * **Zero from a sender that does not walk.** A batch whose delegated signals
     * carry no `within` — synthesised on a server, replayed from a fixture, sent
     * by a host that turned the walk off — adds nothing here, exactly as a batch
     * with no view key adds nothing to `views`.
     */
    readonly engaged: number;
    readonly dwellMs: number;
    readonly activations: number;
    readonly opens: number;
    readonly closes: number;
};

type FunnelEnd = {
    readonly nodeId: NodeId;
    readonly kind: ReaderSignalKind;
};

type FunnelPair = {
    readonly from: FunnelEnd;
    readonly to: FunnelEnd;
};

type FunnelAnswer = {
    readonly treeId: TreeId;
    readonly revision: number;
    readonly pair: FunnelPair;
    /** Views that satisfied `from`. */
    readonly reached: number;
    /** Views that satisfied both. Never greater than `reached`. */
    readonly converted: number;
};

type Rollup = {
    readonly tallies: readonly ReaderTally[];
    readonly funnels: readonly FunnelAnswer[];
    /** Distinct page views seen, across every tree and revision in the input. */
    readonly views: number;
    /**
     * Batches that carried no view key.
     *
     * Their occurrences are counted like any other; their views are not, because
     * there is no honest number to add. Treating each uncorrelated batch as its
     * own view would inflate every denominator by however often a page happened
     * to flush, which is a number about the network rather than about readers.
     * Reported so a portal can say the rate is computed over fewer views than the
     * totals, instead of showing a rate that is quietly wrong.
