     * judged proposal appears in exactly one segment, so the segments sum to
     * `overall` — the split is a partition, not a sample.
     *
     * Ordered by policy name, with the unrecorded segment last, so a reader
     * comparing two windows is comparing rows in the same order.
     */
    readonly byPolicy: readonly PolicyCalibration[];
    /** Proposals that produced no verdict, by why. Never in a denominator. */
    readonly unjudged: Readonly<Record<UnjudgedReason, number>>;
    /**
     * Records the fold could not attribute to a proposal, carried through rather
     * than dropped — the same reason `EpisodeFold` returns them. A rate computed
     * over a window that silently lost records is a rate over a denominator it
     * changed without saying so.
     */
    readonly unattributed: number;
    /**
     * Proposals the runtime authored rather than a model — the inverse behind a
     * revert, say. Segmented rather than dropped: they carry a confidence because
     * every proposal does, but nobody graded it, so scoring them would measure the
     * constant the runtime stamps. Reporting the count keeps that visible instead
     * of leaving a reader to wonder where the undos went.
     */
    readonly runtimeAuthored: number;
};

type EpisodeFailure = TelemetryFailure & {
    readonly stage: FailureStage;
};

type ProposalEpisode = {
    readonly proposalId: ProposalId;
    /** Set when this proposal replaced one the Gate refused. */
    readonly repairOf?: ProposalId;
    readonly provenance: Provenance;
    readonly rationale: string;
    readonly delta: TreeDelta;
    readonly proposedAt: string;
    readonly assessment?: AssessmentSummary;
    readonly disposition?: Disposition;
    /** The Gate held it and custody succeeded, so a human was asked. */
    readonly held: boolean;
    /** A refusal that was handed back for one more attempt. */
    readonly repairRequested: boolean;
    readonly answer?: EpisodeAnswer;
    /**
     * Who answered. Distinct from `provenance.actor`, which is who asked — a hold
     * exists to put a second person in the way of a change, and an episode that
     * showed only the asker would make the two look like one.
     */
    readonly answeredBy?: string;
    /** Applied in memory. Present without `committedRevision` means it did not persist. */
    readonly appliedRevision?: number;
    readonly committedRevision?: number;
    readonly failure?: EpisodeFailure;
    readonly settledAt?: string;
};

type EpisodeResolution = {
    readonly kind: "committed";
    readonly proposalId: ProposalId;
    readonly revision: number;
} | {
    readonly kind: "refused";
    readonly proposalId: ProposalId;
} | {
    readonly kind: "awaiting-answer";
    readonly proposalId: ProposalId;
} | {
    readonly kind: "discarded";
    readonly proposalId: ProposalId;
} | {
    readonly kind: "not-interpreted";
    readonly failure: EpisodeFailure;
} | {
    readonly kind: "not-writable";
    readonly failure: EpisodeFailure;
} | {
    readonly kind: "failed";
    readonly proposalId: ProposalId;
    readonly failure: EpisodeFailure;
}
/** Nothing in this window settled it — still in flight, or the page ends mid-episode. */
 | {
    readonly kind: "open";
};

type IntentEpisode = {
    readonly intentId: IntentId;
    readonly treeId: TreeId;
    /** Absent when the window opened after the intent was received. */
    readonly intent?: IntentSummary;
    /**
     * The policy this intent was last resolved to be judged under. Absent when
     * the window opened after resolution, or when the records predate it.
     *
     * "Last" matters for a proposal that was held and later confirmed: the Gate
     * resolves again on the second look, so a host that narrowed its policy in
     * between shows two resolutions and this keeps the one that decided the
     * outcome. Each proposal's disposition carries the policy that judged that
     * proposal, which is the finer-grained truth.
     */
    readonly policyId?: string;
    readonly startedAt: string;
    readonly proposals: readonly ProposalEpisode[];
    readonly resolution: EpisodeResolution;
};

type EpisodeFold = {
    readonly episodes: readonly IntentEpisode[];
    /**
     * Records that name a proposal this window never saw proposed. Returned
     * rather than discarded: a fold that quietly dropped them would report a
     * refusal rate over a denominator it had silently changed.
     */
    readonly unattributed: readonly RecordedTelemetry[];
};

type EpisodeTally = {
    readonly episodes: number;
    readonly proposals: number;
    /** Proposals the Gate would not apply on its own. */
    readonly held: number;
    /** Proposals made to replace one the Gate refused. */
    readonly repairs: number;
    /**
     * Every kind, including the ones that did not happen. A resolution absent from
     * this map and one that occurred zero times are different claims, and only one
     * of them is true.
     */
    readonly byResolution: Readonly<Record<EpisodeResolutionKind, number>>;
};

type TelemetryFailure = {
    readonly code: string;
    readonly detail: string;
};

type IntentSummary = {
    readonly intentId: IntentId;
    readonly origin: IntentOrigin;
    readonly actor?: string;
    readonly baseRevision: number;
    readonly scopeNodeId?: NodeId;
    readonly utteranceLength: number;
    readonly observedAt: string;
};

type AssessmentSummary = {
    readonly proposalId: ProposalId;
    readonly stakes: StakeLevel;
    readonly reversible: boolean;
    readonly operationCount: number;
    readonly insertedNodeCount: number;
    readonly removedNodeCount: number;
    readonly movedNodeCount: number;
    readonly configuredNodeCount: number;
    readonly touchedPrimitiveTypes: readonly PrimitiveType[];
    /** Absent on a record written before the field existed, never defaulted. */
    readonly removedPrimitiveTypes?: readonly PrimitiveType[];
    readonly relocatedPrimitiveTypes?: readonly PrimitiveType[];
    readonly relocatedNodeCount?: number;
    readonly shallowestAffectedDepth: number;
    readonly retainedNodeCount: number;
    readonly irreversibilityReasons: readonly string[];
};

type TelemetryEvent = {
    readonly type: "intent-received";
    readonly intent: IntentSummary;
} | {
    readonly type: "policy-resolved";
    readonly intentId: IntentId;
    readonly policyId: string;
    /** Absent on a record written before the Gate fingerprinted policies. */
    readonly policyFingerprint?: string;
} | {
    readonly type: "interpretation-failed";
    readonly intentId: IntentId;
    readonly failure: TelemetryFailure;
} | {
    readonly type: "change-proposed";
    readonly proposal: ProposedChange;
} | {
    readonly type: "assessment-failed";
    readonly proposalId: ProposalId;
    readonly failure: TelemetryFailure;
} | {
    readonly type: "change-assessed";
    readonly assessment: AssessmentSummary;
} | {
    readonly type: "disposition-decided";
    readonly proposalId: ProposalId;
    readonly disposition: Disposition;
} | {
    readonly type: "repair-requested";
    readonly refusedProposalId: ProposalId;
    readonly reason: DispositionReason;
} | {
    readonly type: "repair-failed";
    readonly refusedProposalId: ProposalId;
    readonly failure: TelemetryFailure;
} | {
    readonly type: "change-applied";
    readonly proposalId: ProposalId;
    readonly revision: number;
} | {
    readonly type: "application-failed";
    readonly proposalId: ProposalId;
    readonly failure: TelemetryFailure;
} | {
    readonly type: "intent-not-writable";
    readonly intentId: IntentId;
    readonly failure: TelemetryFailure;
} | {
    readonly type: "proposal-held";
    readonly proposalId: ProposalId;
} | {
    readonly type: "hold-failed";
    readonly proposalId: ProposalId;
    readonly failure: TelemetryFailure;
} | {
    readonly type: "hold-confirmed";
    readonly proposalId: ProposalId;
    readonly actor?: string;
} | {
    readonly type: "hold-discarded";
    readonly proposalId: ProposalId;
    readonly actor?: string;
} | {
    readonly type: "change-committed";
    readonly proposalId: ProposalId;
    readonly revision: number;
} | {
    readonly type: "commit-failed";
    readonly proposalId: ProposalId;
    readonly failure: TelemetryFailure;
};

type TelemetryRecord = {
    readonly treeId: TreeId;
    readonly occurredAt: string;
    readonly event: TelemetryEvent;
};

type TelemetryError = {
    readonly code: "unavailable";
    readonly detail: string;
};

type RecordedTelemetry = TelemetryRecord & {
    readonly seq: number;
    /**
     * When the journal learned of the record, which is not `occurredAt`.
     *
     * Both are here because they answer different questions and only one of them
     * the journal can vouch for. `occurredAt` is what the host said, and a host
     * that sets it wrongly — a skewed serverless clock, a replayed batch — is
     * describing its own timeline. `recordedAt` is stamped on arrival, so it is
     * the only timestamp retention may be measured against: an age a writer can
     * choose is an age a writer can dodge.
     */
    readonly recordedAt: string;
};

type TelemetryReadRequest = {
    /** Absent reads every tree the handle can see, which is the scope rule. */
    readonly treeId?: TreeId;
    /** A cursor from a previous page's `older`/`newer`, passed back unread. */
    readonly cursor?: string;
    /**
     * Default `newer`, which with no cursor is the oldest page. `older` with no
     * cursor is the newest page — the read a reader almost always wants first.
     */
    readonly direction?: PageDirection;
    readonly limit?: number;
};

type TelemetryPage = PageEnds & {
    /**
     * Always ascending by `seq`, whichever end the page was taken from.
     *
     * The direction is a property of *which* records a page contains, never of
     * the order they arrive in. `episodesOf` folds a stream in arrival order, and
     * a page that sometimes came back reversed would make every consumer
     * responsible for knowing which — and silently wrong when it guessed.
     */
    readonly records: readonly RecordedTelemetry[];
};

interface TelemetryJournal {
    readonly record: (records: readonly TelemetryRecord[]) => Promise<Result<void, TelemetryError>>;
    readonly read: (request?: TelemetryReadRequest) => Promise<Result<TelemetryPage, TelemetryError>>;
    readonly forget: (request: ForgetRequest) => Promise<Result<ForgetOutcome, TelemetryError>>;
}

type RetentionPlan = {
    /**
     * Forget every record below this position. `null` when nothing may go yet —
     * either the journal holds nothing old enough, or the oldest thing in it is
     * an episode still waiting on someone.
     */
    readonly before: number | null;
    readonly forgets: number;
    /** Older than the horizon, kept because their own episode is unsettled. */
    readonly keptUnsettled: number;
    /**
     * Older than the horizon and settled, kept only because an unsettled episode
     * sits in front of them. Reported separately because it is the price of the
     * prefix rule, and a host watching this number stay large has learned that
     * something very old is still waiting on an answer.
     */
    readonly keptBehind: number;
    readonly unsettledEpisodes: number;
};

type RetentionRequest = {
    readonly policy: RetentionPolicy;
    readonly clock?: Clock;
    readonly scanLimit?: number;
};

type RetentionOutcome = {
    readonly outcome: "forgot";
    readonly plan: RetentionPlan;
    readonly removed: number;
} | {
    readonly outcome: "nothing-to-forget";
    readonly plan: RetentionPlan;
}
/** The policy or the clock was not usable. Nothing was read and nothing was deleted. */
 | {
    readonly outcome: "refused";
    readonly reason: string;
} | {
    readonly outcome: "unavailable";
    readonly error: TelemetryError;
};

type TelemetryCollector = {
    readonly sink: EventSink;
    /** Not yet written. Exposed so a host can decide a flush is worth the round trip. */
    readonly pending: () => readonly TelemetryRecord[];
    /** Records this collector could not hold or could not write. */
    readonly dropped: () => number;
    /**
     * Writes what has been collected and empties the buffer, whether or not the
     * write succeeded. Records are not retained for a retry: a journal that is
     * failing will fail the retry too, and a queue that grows while it drains
     * moves the outage into the write path.
     */
    readonly flush: () => Promise<Result<void, TelemetryError>>;
};

